  100% { background-position: 200% center; }
}

/* ==========================================================================
   OPENING GATE — full-screen overlay with ambient zoom + tap-to-enter
   ========================================================================== */

/* Lock scroll while gate is active */
body.gate-active {
  overflow: hidden;
  height: 100vh;
}

/* Gate wrapper */
#gate {
  position: fixed;
  inset: 0;
  z-index: 9999;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% 30%, var(--maroon-800) 0%, var(--maroon-950) 65%, #1c0509 100%);
}

#gate.gate-hidden {
  display: none;
}

/* Ambient gold glow, replaces the photo backdrop */
.gate-glow {
  position: absolute;
  inset: -10%;
  background:
    radial-gradient(circle at 50% 18%, rgba(226, 199, 147, 0.16) 0%, transparent 45%),
    radial-gradient(circle at 15% 85%, rgba(200, 169, 106, 0.10) 0%, transparent 50%),
    radial-gradient(circle at 85% 80%, rgba(200, 169, 106, 0.10) 0%, transparent 50%);
  animation: gateGlowDrift 16s ease-in-out infinite alternate;
}

@keyframes gateGlowDrift {
  from { transform: scale(1) rotate(0deg); }
  to   { transform: scale(1.12) rotate(2deg); }
}

/* Dark gradient overlay */
.gate-fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(60, 20, 30, 0.35) 0%,
    rgba(60, 20, 30, 0.15) 30%,
    rgba(80, 30, 40, 0.30) 60%,
    rgba(40, 15, 22, 0.75) 100%
  );
}

/* Radial vignette */
.gate-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(60, 20, 30, 0.55) 100%);
  pointer-events: none;
}

/* Content sits above the image + fade */
.gate-content {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding: 40px 24px;
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

/* Gold corner frame brackets */
.gate-corner {
  position: absolute;
  width: 44px;
  height: 44px;
  border-color: var(--gold);
  border-style: solid;
  opacity: 0.75;
}

.gate-corner.tl { top: 28px;    left: 28px;   border-width: 1px 0 0 1px; }
.gate-corner.tr { top: 28px;    right: 28px;  border-width: 1px 1px 0 0; }
.gate-corner.bl { bottom: 28px; left: 28px;   border-width: 0 0 1px 1px; }
.gate-corner.br { bottom: 28px; right: 28px;  border-width: 0 1px 1px 0; }

/* Bismillah text */
.gate-bismillah {
  font-family: var(--font-script);
  font-size: clamp(32px, 5.5vw, 52px);
  color: var(--gold-light);
  letter-spacing: 0.04em;
  text-shadow: 0 2px 24px rgba(200, 169, 106, 0.40);
  opacity: 0;
  filter: blur(6px);
  transform: translateY(-16px) scale(0.94);
  animation: gateBismillahIn 1.6s cubic-bezier(0.19, 1, 0.22, 1) 0.3s forwards,
             gateBismillahGlow 3.5s ease-in-out 2s infinite;
  margin-bottom: 28px;
}

@keyframes gateBismillahIn {
  0%   { opacity: 0; filter: blur(6px); transform: translateY(-16px) scale(0.94); }
  100% { opacity: 1; filter: blur(0);   transform: translateY(0) scale(1); }
}

@keyframes gateBismillahGlow {
  0%, 100% { text-shadow: 0 2px 24px rgba(200, 169, 106, 0.35); }
  50%       { text-shadow: 0 2px 34px rgba(200, 169, 106, 0.65); }
}

/* Ornament divider (line–diamond–line) */
.gate-ornament {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 24px;
  opacity: 0;
  animation: gateElementFadeIn 1s ease 1s forwards;
}

.gate-line {
  width: 52px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}

.gate-line:last-child {
  background: linear-gradient(90deg, var(--gold), transparent);
}

.gate-diamond {
  width: 7px;
  height: 7px;
  background: var(--gold);
  transform: rotate(45deg);
}

/* Label text */
.gate-label {
  font-size: 11px;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--gold);
  opacity: 0;
  animation: gateElementFadeUp 1s ease 1.2s forwards;
  margin-bottom: 18px;
}

/* Script names */
.gate-names {
  font-family: var(--font-script);
  font-size: clamp(40px, 8vw, 72px);
  color: var(--peach);
  line-height: 1;
  opacity: 0;
  animation: gateElementFadeUp 1.1s ease 1.4s forwards;
  margin-bottom: 14px;
  text-shadow: 0 4px 30px rgba(0, 0, 0, 0.4);
}

/* Date */
.gate-date {
  font-family: var(--font-serif);
  font-size: clamp(13px, 2vw, 16px);
  letter-spacing: 0.3em;
  color: rgba(232, 197, 176, 0.70);
  opacity: 0;
  animation: gateElementFadeUp 1s ease 1.6s forwards;
  margin-bottom: 56px;
}

/* Pulsing tap ring + icon */
.gate-tap {
  position: relative;
  width: 60px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  animation: gateElementFadeIn 1s ease 2s forwards;
  margin-bottom: 14px;
}

.gate-tap-ring {
  position: absolute;
  inset: 0;
  border: 1px solid var(--gold);
  border-radius: 50%;
  animation: gateTapPulse 2.2s ease-out infinite;
}

.gate-tap-icon {
  position: relative;
  z-index: 1;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--gold-light), var(--gold-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green-dark);
  font-size: 16px;
  box-shadow: 0 8px 24px rgba(200, 169, 106, 0.35);
}

@keyframes gateTapPulse {
  0%   { transform: scale(1);   opacity: 0.8; }
  100% { transform: scale(1.7); opacity: 0;   }
}

/* "Tap to Open" label */
.gate-tap-text {
  font-size: 11px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(232, 197, 176, 0.75);
  opacity: 0;
  animation: gateElementFadeIn 1s ease 2.1s forwards;
}

/* ===== GATE CLOSING TRANSITION ===== */
#gate.gate-closing .gate-content > * {
  transition: opacity 0.6s ease, transform 0.6s ease, filter 0.6s ease;
}

#gate.gate-closing .gate-bismillah {
  opacity: 0;
  filter: blur(10px);
  transform: translateY(-24px) scale(1.06);
  animation: none;
}

#gate.gate-closing .gate-ornament,
#gate.gate-closing .gate-label,
#gate.gate-closing .gate-date,
#gate.gate-closing .gate-tap,
#gate.gate-closing .gate-tap-text {
  opacity: 0;
  transform: translateY(-10px);
  animation: none;
}

#gate.gate-closing .gate-names {
  opacity: 0;
  transform: translateY(-10px) scale(1.04);
  animation: none;
  transition-delay: 0.08s;
}

#gate.gate-closing .gate-corner {
  opacity: 0;
  transition: opacity 0.5s ease;
}

#gate.gate-closing .gate-fade,
#gate.gate-closing .gate-vignette {
  transition: opacity 0.9s ease 0.15s;
  opacity: 0;
}

#gate.gate-closing .gate-glow {
  transition: opacity 1.1s ease, transform 1.1s cubic-bezier(0.19, 1, 0.22, 1);
  opacity: 0;
  transform: scale(1.25);
}

#gate.gate-closing {
  transition: opacity 0.9s ease 0.35s, visibility 0.9s ease 0.35s;
  opacity: 0;
  pointer-events: none;
}

/* Gate-specific keyframes (prefixed to avoid conflicts) */
@keyframes gateElementFadeUp {
  to { opacity: 1; transform: translateY(0); }
}

@keyframes gateElementFadeIn {
  to { opacity: 1; }
}


/* ===== css/animations.css ===== */
/* ===== SCROLL REVEAL ANIMATIONS (custom AOS-like) ===== */
[data-aos] {
  transition: opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94),
              transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

[data-aos="fade-up"]    { opacity: 0; transform: translateY(40px); }
[data-aos="fade-up"].aos-animate    { opacity: 1; transform: translateY(0); }
[data-aos="fade-down"]  { opacity: 0; transform: translateY(-40px); }
[data-aos="fade-down"].aos-animate  { opacity: 1; transform: translateY(0); }
[data-aos="fade-left"]  { opacity: 0; transform: translateX(40px); }
[data-aos="fade-left"].aos-animate  { opacity: 1; transform: translateX(0); }
[data-aos="fade-right"] { opacity: 0; transform: translateX(-40px); }
[data-aos="fade-right"].aos-animate { opacity: 1; transform: translateX(0); }
[data-aos="scale-in"]   { opacity: 0; transform: scale(0.85); }
[data-aos="scale-in"].aos-animate   { opacity: 1; transform: scale(1); }
[data-aos="fade-in"]    { opacity: 0; }
[data-aos="fade-in"].aos-animate    { opacity: 1; }
[data-aos="blur-reveal"] { opacity: 0; filter: blur(10px); transform: translateY(16px) scale(0.98); }
[data-aos="blur-reveal"].aos-animate { opacity: 1; filter: blur(0); transform: translateY(0) scale(1); }
[data-aos="zoom-reveal"] { opacity: 0; transform: scale(1.12); }
[data-aos="zoom-reveal"].aos-animate { opacity: 1; transform: scale(1); }

[data-aos="blur-reveal"],
[data-aos="zoom-reveal"] {
  transition: opacity 1s cubic-bezier(0.25, 0.46, 0.45, 0.94),
              filter 1s cubic-bezier(0.25, 0.46, 0.45, 0.94),
              transform 1s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* ===== DELAY UTILITIES ===== */
[data-aos-delay="100"] { transition-delay: 100ms; }
[data-aos-delay="200"] { transition-delay: 200ms; }
[data-aos-delay="300"] { transition-delay: 300ms; }
[data-aos-delay="400"] { transition-delay: 400ms; }
[data-aos-delay="500"] { transition-delay: 500ms; }
[data-aos-delay="600"] { transition-delay: 600ms; }

/* ===== SHIMMER TEXT ===== */
.shimmer-gold {
  background: linear-gradient(
    90deg,
    var(--gold) 0%, var(--gold-light) 30%,
    var(--peach) 50%, var(--gold-light) 70%, var(--gold) 100%
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: shimmerText 3s linear infinite;
}

@keyframes shimmerText { to { background-position: 200% center; } }

/* ===== HOVER LIFT ===== */
.hover-lift {
  transition: transform 0.4s ease, box-shadow 0.4s ease;
}

.hover-lift:hover {
  transform: translateY(-8px);
  box-shadow: 0 24px 60px rgba(143, 168, 194, 0.18);
}

/* ===== FLOAT ANIMATIONS ===== */
.float-1 { animation: floatY 6s ease-in-out infinite; }
.float-2 { animation: floatY 7s ease-in-out 1s infinite; }
.float-3 { animation: floatY 8s ease-in-out 2s infinite; }

/* ===== ORNAMENT SPIN ===== */
.ornament-spin {
  display: inline-block;
  animation: gentleSpin 20s linear infinite;
}

@keyframes gentleSpin { to { transform: rotate(360deg); } }

/* ===== GLOW PULSE ===== */
.glow-gold { animation: glowPulse 2s ease-in-out infinite; }

@keyframes glowPulse {
  0%, 100% { box-shadow: 0 0 20px rgba(201, 123, 138, 0.28); }
  50%       { box-shadow: 0 0 40px rgba(143, 168, 194, 0.45); }
}

/* ===== COUNTDOWN FLIP ===== */
.countdown-number.flip { animation: countFlip 0.3s ease; }

@keyframes countFlip {
  0%   { transform: translateY(0);   opacity: 1; }
  50%  { transform: translateY(-8px); opacity: 0; }
  100% { transform: translateY(0);   opacity: 1; }
}

/* ===== REDUCED MOTION ===== */
@media (prefers-reduced-motion: reduce) {
  [data-aos] {
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
  }
  .float-1, .float-2, .float-3 { animation: none; }
  .shimmer-gold {
    animation: none;
    background: var(--gold);
    -webkit-background-clip: unset;
    -webkit-text-fill-color: unset;
    background-clip: unset;
    color: var(--gold);
  }
  .glow-gold { animation: none; }
}


/* ===== css/responsive.css ===== */
/* ==========================================================================
   RESPONSIVE.CSS — all breakpoints
   ========================================================================== */

/* ===== TABLET: 900px ===== */
@media (max-width: 900px) {
  .couple-content .parents-grid {
    grid-template-columns: 1fr;
    max-width: 420px;
    margin-left: auto;
    margin-right: auto;
  }

  .couple-monogram-frame {
    width: min(60vw, 260px);
    height: min(60vw, 260px);
  }

  .events-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
  }

  .parents-grid {
    grid-template-columns: 1fr;
    max-width: 420px;
    margin-left: auto;
    margin-right: auto;
  }

  .countdown-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .timeline::before {
    left: 24px;
  }

  .timeline-item {
    grid-template-columns: auto 1fr;
    gap: 20px;
  }

  .timeline-item:nth-child(odd) .timeline-text {
    text-align: left;
    order: 0;
  }

  .timeline-item:nth-child(even) .timeline-text {
    grid-column: auto;
  }

  .timeline-item:nth-child(even) .timeline-empty {
    display: none;
  }

  .timeline {
    padding: 0 0 0 12px;
  }

  /* Arch: slightly narrower stage on tablet */
  .hero__stage { min-height: 74vh; }
  .arch-frame  { width: min(72vw, 320px); height: min(72vw, 400px); }
}

/* ===== MOBILE: 640px ===== */
@media (max-width: 640px) {
  /* Arch responsive */
  .hero__stage  { min-height: 70vh; padding: 0 16px; }
  .arch-frame   { width: 82vw; height: 88vw; max-height: 60vh; }
  .garland      { width: 88vw; top: -14px; }

  .hero__names  { flex-direction: column; align-items: center; gap: 0; }
  .hero__name   { font-size: clamp(1.8rem, 8vw, 2.8rem); }
  .hero__amp    { font-size: clamp(1.4rem, 6vw, 2rem); }
  .hero__date   { font-size: 0.85rem; letter-spacing: 0.2em; }
  .hero__venue-line { font-size: 0.72rem; }

  /* Music toggle: shift left slightly so it doesn't overlap scroll cue */
  .music-toggle { bottom: 20px; right: 16px; width: 46px; height: 46px; }
}

/* ===== MOBILE: 480px ===== */
@media (max-width: 480px) {
  .nav { padding: 16px 20px; }

  #hero { min-height: 100svh; }

  #opening,
  #couple,
  #events,
  #venue,
  #countdown,
  #quote-section,
  #gallery,
  #love-story,
  #rsvp,
  #parents {
    padding: 80px 16px;
  }

  .venue-map-frame { height: 240px; }
  .venue-info { padding: 32px 20px 36px; }

  .countdown-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .countdown-box { padding: 24px 12px; }

  .countdown-number { font-size: clamp(36px, 10vw, 56px); }

  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .event-card  { padding: 36px 20px; }

  .couple-monogram-frame { width: min(58vw, 220px); height: min(58vw, 220px); }

  footer { padding: 60px 16px 32px; }

  .maps-btn {
    width: 100%;
    justify-content: center;
  }

  .ornament-line { width: 50px; }

  /* Arch on small mobile */
  .arch-frame   { width: 88vw; height: 92vw; max-height: 56vh; }
  .arch-cta__label { font-size: 0.6rem; letter-spacing: 0.2em; }
}

/* ===== EXTRA SMALL: 360px ===== */
@media (max-width: 360px) {
  .arch-frame { width: 92vw; height: 96vw; max-height: 54vh; }

  .hero__name {
    font-size: clamp(1.6rem, 7vw, 2.2rem);
  }

  .countdown-grid { gap: 10px; }
}